  } else if (telefonoLimpio.startsWith('55')) {
    // Brasil u otro caso ya con código de país, se deja como está
  } else if (telefonoLimpio.length >= 8) {
    telefonoLimpio = '549' + telefonoLimpio;
  }

  lead.CELULAR = telefonoLimpio || telefono;

  return true;
});

